query Metafields($entityId: Int!, $namespace: String!) {
  site {
    product(entityId: $entityId) {
      entityId
      name
      metafields(namespace: $namespace, first: 25) {
        pageInfo {
          hasNextPage
          endCursor
        }
        edges {
          node {
            id
            entityId
            key
            value
            description
          }
        }
      }
      variants(first: 3) {
        edges {
          node {
            entityId
            sku
            metafields(namespace: $namespace, first: 25) {
              edges {
                node {
                  entityId
                  key
                  value
                }
              }
            }
          }
        }
      }
    }
  }
}
